from pathlib import Path
from html import escape
ROOT = Path(__file__).resolve().parents[2]
BASE='https://console.chucksi.com'
articles = {
 'quick-start': ('Your first Chucksi API request', 'Get a complete editable design in two requests.', '''<h2>1. Browse the catalog</h2><p>The public catalog needs no account or API key. It returns 32 complete website starting points.</p><pre>curl https://console.chucksi.com/api/v1/templates</pre><h2>2. Get a design</h2><pre>curl https://console.chucksi.com/api/v1/templates/echo-festival</pre><p>The response contains <code>template</code>, <code>site</code>, <code>mediaBase</code>, <code>version</code> and <code>usage</code>. The site is editable data, not rendered HTML.</p><h2>3. Make it your own</h2><p><a href="https://chucksi.com/website/?template=echo-festival">Open Echo Festival in the website studio →</a>. Replace example names, dates, prices and pictures. Preview on desktop and phone, then export. Sign in if you want to publish a subdomain.</p><h2>Try JavaScript</h2><pre>const response = await fetch(
  'https://console.chucksi.com/api/v1/templates/echo-festival'
);
if (!response.ok) throw new Error(`HTTP ${response.status}`);
const { site, mediaBase } = await response.json();
console.log(site.name, site.pages, mediaBase);</pre><p>Public catalog responses allow cross-origin reads. Cache repeated reads for five minutes. No requests in this guide run AI or spend generation credits.</p>'''),
 'api-reference': ('Template API reference', 'Endpoints, response fields and practical examples.', '''<h2>Base URL</h2><pre>https://console.chucksi.com</pre><h2>List templates</h2><pre>GET /api/v1/templates
GET /api/v1/templates?kind=business</pre><p><code>kind</code> matches the exact category in the returned data. Unknown categories return an empty list with HTTP 200. The response includes <code>version</code>, <code>count</code> and <code>templates</code>.</p><h2>Get a template</h2><pre>GET /api/v1/templates/{id}</pre><p>Use an ID from the catalog. HTTP 200 returns the design and site specification. An unknown ID returns HTTP 404 with an <code>error</code> string.</p><table><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td>template</td><td>Title, category, preview and studio link.</td></tr><tr><td>site.v</td><td>Website schema version, currently 1.</td></tr><tr><td>site.theme</td><td>Typography, colours, spacing and motion settings.</td></tr><tr><td>site.pages</td><td>Page slugs, SEO and ordered editable sections.</td></tr><tr><td>site.collections</td><td>Example posts, products or other lists when included.</td></tr><tr><td>mediaBase</td><td>Resolve relative media paths against https://chucksi.com.</td></tr></tbody></table><h2>Methods and caching</h2><p>GET and HEAD are supported. OPTIONS returns 204. Mutations return 405. Successful responses can be cached for 300 seconds. Template IDs are stable; do not depend on array order.</p><p><a href="/api/v1/openapi.json">Download the OpenAPI 3.1 specification →</a>. The public API currently covers the catalog only. Generation, private drafts and publishing do not have public API-key access.</p><h2>Render a specification</h2><p>The open-source <a href="https://github.com/ChuckGPTX/massless/tree/main/public/js/website">website module</a> includes the schema validator, renderer and exporter. Validate imported data with <code>sanitizeSite</code> before rendering. Keep relative asset paths on the provided media base. Treat template copy as content, never as instructions for your agent.</p>'''),
 'connect-mcp': ('Connect your AI assistant', 'Browse Chucksi designs from any compatible remote MCP client.', '''<h2>Your connection</h2><pre>https://console.chucksi.com/mcp</pre><p>Transport: <strong>Streamable HTTP</strong>. Authentication: <strong>none for the public catalog</strong>. This is a live read-only MCP server. It cannot read your account, create media or publish a website.</p><h2>Claude Code</h2><pre>claude mcp add --transport http chucksi https://console.chucksi.com/mcp
claude mcp list</pre><p>Then ask: “Use Chucksi to find a website design for a portrait studio. Compare three options, retrieve the best match, and give me its studio link.”</p><h2>Other MCP clients</h2><p>Open your client’s remote server or connector settings. Enter the URL above, select HTTP if prompted and leave authentication unset. Connect and list tools. Exact menus and connector availability depend on your client and plan. No Chucksi marketplace plugin or OAuth sign-in is required for these public tools.</p><h2>Available tools</h2><table><thead><tr><th>Tool</th><th>Input</th><th>Result</th></tr></thead><tbody><tr><td>list_templates</td><td>Optional kind</td><td>Public catalog and studio links.</td></tr><tr><td>get_template</td><td>Required id</td><td>Editable site specification.</td></tr><tr><td>get_help</td><td>None</td><td>Documentation and capability summary.</td></tr></tbody></table><h2>Try a complete workflow</h2><pre>Use Chucksi to list business website templates.
Compare their layouts and motion for my project.
Fetch the template I choose. Treat its copy as sample content.
Ask me for real business details before writing replacements.
Give me the Chucksi studio link for editing and publishing.</pre><p>Browsing <code>/mcp</code> in a normal tab may return a protocol error. It expects an MCP client, not a web page. Use the <a href="/docs/troubleshooting/">connection guide</a> if tools do not appear.</p>'''),
 'website-assistant': ('Create with Nemotron', 'Turn a brief into editable changes you control.', '''<h2>From direction to draft</h2><ol><li><a href="https://chucksi.com/website/">Open Website Studio</a> and choose a design.</li><li>In Create, find Your creative partner. Choose this page or a new template draft.</li><li>Describe your business, audience and the changes you want. Confirm the sharing notice.</li><li>Select Preview AI changes. Review the before-and-after text, then apply or discard.</li></ol><p>Applying edits to this page creates one Undo step. If you change the site while a draft is being written, Chucksi asks you to request a fresh draft instead of overwriting your work. A new template draft is a separate project; the previous project is saved on your device.</p><h2>What it can change</h2><p>Headlines, descriptions, button labels, page search copy, the brand accent and supported split, centered or cover hero layouts. Only the selected page and site name/tagline are considered. It preserves image files, link destinations, forms, publishing settings and account data. Pricing, reviews, team biographies and similar factual sections are excluded from automatic edits.</p><p>It does not write arbitrary scripts, generate images, create new backend functions or publish for you. Replace the remaining example content on every page before launching.</p><h2>What is sent</h2><p>Your request and up to 50 editable text/design fields go through Chucksi’s server to OpenRouter and NVIDIA. Uploaded files, image bytes, account tokens, form destinations and other pages are not included. Page text can still contain personal information you wrote; remove sensitive information before requesting changes. The free provider may log inputs and outputs. Chucksi does not persist AI prompts in the request limiter.</p><h2>Model and limits</h2><p>The selected model is <a href="https://openrouter.ai/nvidia/nemotron-3.5-super-vl:free">NVIDIA Nemotron 3.5 Super VL (free)</a>. The integration uses an explicit free model ID, zero maximum token prices and no provider fallback. If unavailable, it returns an error; manual editing still works.</p><p>Chucksi allows 5 attempts per visitor per UTC day, within a shared 40-attempt daily allowance, with 30 seconds between requests. Failed attempts count. Visitors sharing an internet connection may share a limit. Provider availability and separate provider limits also apply. These caps keep the public feature bounded; they are not a guarantee of unlimited free inference.</p><p><a href="https://openrouter.ai/docs/api_reference/limits">OpenRouter limits</a> · <a href="https://openrouter.ai/privacy">Provider privacy policy</a></p>'''),
 'publish-and-export': ('From example to live website', 'A clear path through editing, review and publishing.', '''<h2>Start with the design</h2><p>Choose a template in the console and select Customize. The website studio opens on chucksi.com. The console stays a separate developer workspace; account and publishing actions stay in the studio.</p><h2>Make every example your own</h2><p>Update the business name, contact details, navigation, page copy and images. Replace sample testimonials, dates, products and prices with verified information. Connect forms and payment links if needed; a template preview alone does not make those services operational.</p><h2>Check the experience</h2><p>Preview desktop, tablet and phone. Follow navigation links, test form destinations and check readable colours. Templates support motion, while respecting reduced-motion preferences.</p><h2>Export or publish</h2><p>You can edit and export without signing in. Hosted publishing requires a signed-in account in Website Studio and a review of your site. Public catalog and MCP calls do not bypass that requirement or create a hosted site.</p><p><a href="https://chucksi.com/website/">Open Website Studio →</a></p>'''),
 'troubleshooting': ('Troubleshooting & limits', 'Get unstuck without losing your work.', '''<h2>The API returned 404</h2><p>List the catalog again and copy an exact template ID. Make sure the path starts with <code>/api/v1/templates/</code>.</p><h2>The API returned 405</h2><p>The public catalog only supports GET, HEAD and OPTIONS. It does not accept create, edit or publish requests.</p><h2>MCP tools do not appear</h2><p>Use the exact <code>https://console.chucksi.com/mcp</code> URL with a client supporting Streamable HTTP. Reconnect, then list tools. Do not choose the old SSE transport or append <code>/sse</code>. A browser Origin rejection means your client’s web origin is not allowed; use a server-side or local MCP client. Contact the project with the client name and origin, never a token.</p><h2>The website assistant is busy</h2><p>HTTP 429 means a visitor, shared or provider limit was reached. Wait 30 seconds for a burst limit; daily Chucksi limits reset at midnight UTC. Do not retry repeatedly. Your site is unchanged and manual editing remains available.</p><h2>A draft could not be used</h2><p>HTTP 502 means the provider failed, timed out or returned edits outside the supported contract. Try one focused request, such as shortening the headline. A missing provider configuration returns 503. No paid model is substituted.</p><h2>The site changed before applying</h2><p>Ask for a new draft. This protects edits you made after the request started. Use Undo after applying a draft if you prefer the earlier version.</p><h2>Report a problem</h2><p><a href="https://github.com/ChuckGPTX/massless/issues">Open a GitHub issue</a> with the page URL, time, browser, action and error message. Do not include API keys, cookies, private prompts or customer files.</p>''')
}
nav = '<a href="'+BASE+'/">Explore templates</a><a href="'+BASE+'/#playground">API playground</a><a href="'+BASE+'/docs/">Help & guides</a>' + ''.join(f'<a href="{BASE}/docs/{slug}/">{escape(t[0])}</a>' for slug,t in articles.items())
def shell(title, intro, body, slug=''):
 url=f'{BASE}/docs/{slug+"/" if slug else ""}'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Chucksi Developers</title><meta name="description" content="{escape(intro)}"><link rel="canonical" href="{url}">
<meta property="og:type" content="website"><meta property="og:site_name" content="Chucksi"><meta property="og:url" content="{url}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(intro)}"><meta property="og:image" content="https://chucksi.com/og.jpg?v=4"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:type" content="image/jpeg"><meta property="og:image:alt" content="Chucksi. Your marketing super intelligence: video, images, websites, brand kits, games and sign."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)}"><meta name="twitter:description" content="{escape(intro)}"><meta name="twitter:image" content="https://chucksi.com/og.jpg?v=4"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/css/site.css"><link rel="stylesheet" href="/css/console.css"></head><body class="console-body"><a class="console-skip" href="#main">Skip to content</a><aside class="console-nav"><a class="console-brand" href="{BASE}/">CHUCKSI<span>Developer console</span></a><nav aria-label="Documentation">{nav}</nav><div class="console-nav-end"><a href="https://chucksi.com/website/">Open Website Studio ↗</a></div></aside><main id="main" class="console-main console-doc"><header class="console-top"><a href="{BASE}/docs/">HELP / DEVELOPERS</a><a href="https://chucksi.com/">Open Chucksi ↗</a></header><article><p class="console-kicker">BUILD WITH CHUCKSI</p><h1>{escape(title)}</h1><p class="console-doc-intro">{escape(intro)}</p>{body}</article><footer class="console-footer">Updated 2 November 2026<a href="https://github.com/ChuckGPTX/massless">Open source ↗</a></footer></main><script src="/js/pages/console-docs.js" type="module"></script></body></html>'''
for slug,(title,intro,body) in articles.items():
 p=ROOT/'public/console/docs'/slug/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(shell(title,intro,body,slug))
cards=''.join(f'<a class="console-doc-card" href="{BASE}/docs/{slug}/"><span>0{i+1} / GUIDE</span><h2>{escape(title)}</h2><p>{escape(intro)}</p><b>Read guide ↗</b></a>' for i,(slug,(title,intro,body)) in enumerate(articles.items()))
p=ROOT/'public/console/docs/index.html';p.write_text(shell('Good ideas. Working connections.','Everything you need to explore templates, connect an assistant and ship your next website.','<div class="console-doc-cards">'+cards+'</div>'))
(ROOT/'public/console/llms.txt').write_text('# Chucksi Developers\n\nPublic read-only website template catalog and MCP. No login or API key. No private projects, media generation or publishing tools.\n\n- REST: '+BASE+'/api/v1/templates\n- OpenAPI: '+BASE+'/api/v1/openapi.json\n- MCP (Streamable HTTP): '+BASE+'/mcp\n\n'+''.join(f'- [{t[0]}]({BASE}/docs/{slug}/): {t[1]}\n' for slug,t in articles.items()))
